  const cronica = (titulo, texto) => `<h4>${titulo}</h4><p>${texto}</p>`;
  const T = {
    fila: cronica('A fila da cantina', 'Na hora do recreio, a fila da cantina é o lugar mais demorado do mundo. Ontem eu estava nela, com a moeda suando na mão, quando o Caio resolveu contar as moedinhas dele bem na frente do balcão. Uma por uma. A fila inteira bufou. Faltavam dois minutos para o sinal quando chegou a minha vez.<br>— Acabou o pão de queijo — disse a dona Neusa.<br>Voltei para a sala de barriga vazia, mas com uma certeza: amanhã eu trago lanche de casa.'),
    gato: cronica('Visita de segunda-feira', 'Toda segunda-feira, às sete em ponto, um gato laranja aparece na janela da nossa sala. Ele não mia, não pede nada: senta, enrola o rabo e assiste à aula de Matemática com cara de quem entende tudo. A professora já desistiu de espantá-lo. Ontem, quando ela perguntou quanto era sete vezes oito, ele bocejou bem na hora. A turma caiu na risada. Eu, que não sabia a resposta, fiquei com a impressão de que o gato sabia.'),
    controle: cronica('O sumiço do controle', 'Lá em casa, o controle remoto some todo domingo. Meu pai acusa minha irmã, minha irmã acusa o cachorro, e o cachorro, coitado, não acusa ninguém. Viramos as almofadas, olhamos embaixo do sofá, abrimos até a geladeira. Ontem, depois de meia hora de busca, minha avó entrou na sala, olhou para o meu pai e apontou: o controle estava no bolso do roupão dele. Ninguém falou nada. Só o cachorro abanou o rabo, como quem diz: eu sabia.'),
    novelo: cronica('Dejair e o novelo sumido', 'Dejair passava as tardes dormindo no muro da dona Lia. Certo dia, ao acordar, viu que seu novelo de lã preferido tinha sumido. Procurou no quintal, na garagem, e nada. Então ouviu um piado no telhado: um filhote de sabiá estava enroscado na lã, quase caindo da calha. Dejair subiu devagar, com o coração aos pulos, e soltou o fio no último segundo. O filhote voou para o ninho. Dejair ficou sem o novelo, mas ganhou um amigo, que agora canta para ele todas as tardes.'),
    adote: '<div class="anuncio"><span class="an-t">Não compre. Adote!</span><span>Mais de 40 cães e gatos esperam por um lar.</span><span class="an-m">Sábado, das 9h às 16h · Praça da Matriz</span><span class="an-s">Feira Patas Felizes: leve amor para casa.</span><small>Traga documento e comprovante de endereço. Menores só acompanhados de um adulto.</small></div>',
    tenis: '<div class="anuncio"><span class="an-t">Tênis Relâmpago</span><span class="an-s">Calce e voe!</span><span>O tênis mais leve do Brasil chegou: solado macio, cinco cores e cadarço que não desamarra.</span><span class="an-m">Só até domingo: 20% de desconto</span><small>Nas lojas Pé de Vento.</small></div>',
  };

